code='''from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            yield color, cells

def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r,c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    references = {}
    comps = list(_components(grid))
    for color, cells in comps:
        if color != 1:
            references.setdefault(_shape(cells), color)
    for color, cells in comps:
        if color == 1:
            replacement = references.get(_shape(cells))
            if replacement is not None:
                for r,c in cells:
                    out[r][c] = replacement
    return out
'''
